import { Injectable } from '@angular/core';
import { Router } from '@angular/router';
import { BehaviorSubject, Observable, of } from 'rxjs';
import { delay, tap } from 'rxjs/operators';
import { LoginCredentials, AuthResponse } from '../models';

/**
 * Authentication Service
 * 
 * Simplified auth - accepts any username/password.
 * Always uses hardcoded Basic Auth admin:admin for API requests.
 */
@Injectable({
    providedIn: 'root'
})
export class AuthService {
    private readonly IS_LOGGED_IN_KEY = 'is_logged_in';
    private readonly USER_ID_KEY = 'user_id';

    // Hardcoded Basic Auth credentials for API requests
    private readonly API_USERNAME = 'admin';
    private readonly API_PASSWORD = 'admin';

    private isAuthenticatedSubject = new BehaviorSubject<boolean>(this.checkLoggedIn());

    /** Observable for authentication state changes */
    public isAuthenticated$ = this.isAuthenticatedSubject.asObservable();

    constructor(private router: Router) { }

    /**
     * Login - accepts any username/password
     */
    login(credentials: LoginCredentials): Observable<AuthResponse> {
        // Accept any credentials - no validation
        const response: AuthResponse = {
            token: '',
            userId: 1,
            expiresIn: 86400
        };

        return of(response).pipe(
            delay(300),
            tap(() => this.handleAuthSuccess())
        );
    }

    /**
     * Log out current user
     */
    logout(): void {
        localStorage.removeItem(this.IS_LOGGED_IN_KEY);
        localStorage.removeItem(this.USER_ID_KEY);
        this.isAuthenticatedSubject.next(false);
        this.router.navigate(['/login']);
    }

    /**
     * Check if user is logged in
     */
    isAuthenticated(): boolean {
        return this.checkLoggedIn();
    }

    /**
     * Get Basic Auth header - always returns admin:admin
     */
    getBasicAuthHeader(): string {
        return `Basic ${btoa(`${this.API_USERNAME}:${this.API_PASSWORD}`)}`;
    }

    /**
     * Get current user's account ID
     */
    getCurrentUserId(): number {
        return 1; // Always return 1
    }

    /**
     * Handle successful login
     */
    private handleAuthSuccess(): void {
        localStorage.setItem(this.IS_LOGGED_IN_KEY, 'true');
        localStorage.setItem(this.USER_ID_KEY, '1');
        this.isAuthenticatedSubject.next(true);
    }

    /**
     * Check if logged in flag is set
     */
    private checkLoggedIn(): boolean {
        return localStorage.getItem(this.IS_LOGGED_IN_KEY) === 'true';
    }
}
